-- Issues #70/#74 (Korund emergency Presidium session, AI Chairman purge/succession): session records with AI decision records. Additive table only.
CREATE TABLE IF NOT EXISTS korund_presidium_sessions ( id TEXT COLLATE "C" PRIMARY KEY, opened_at BIGINT NOT NULL, resolves_at BIGINT NOT NULL CHECK(resolves_at > opened_at), unrest_at_open BIGINT NOT NULL CHECK(unrest_at_open BETWEEN 0 AND 100), sustained_seconds BIGINT NOT NULL CHECK(sustained_seconds >= 0), chairman_before TEXT COLLATE "C" NOT NULL, resolved_at BIGINT, outcome TEXT COLLATE "C" CHECK(outcome IS NULL OR outcome IN ('survived','purged')), successor TEXT COLLATE "C", purged_seat TEXT COLLATE "C", quota_pct BIGINT, decision_json TEXT COLLATE "C", CHECK((resolved_at IS NULL) = (outcome IS NULL)), CHECK(outcome IS NULL OR outcome <> 'purged' OR (successor IS NOT NULL AND purged_seat IS NOT NULL)) );
CREATE INDEX IF NOT EXISTS idx_korund_presidium_opened ON korund_presidium_sessions(opened_at);
